<script setup lang="ts">
import { ref, watch } from 'vue'
import { MAlert, MBadge, MButton, MCard, MDialog, MEmptyState } from '@getcortexlabs/mavis-web'
import { createBackup, fetchHealth, runMemoryProbe, runDiagnostics, formatDateTime, formatSize, restoreBackup, retryPending, verifyBackup, type BackupSnapshot, type RecoveryHealth } from '../lib/api'
const props = defineProps<{ revision: number }>()
const data = ref<RecoveryHealth>()
const error = ref(''), notice = ref(''), busy = ref(false), confirm = ref(false)
const selected = ref<BackupSnapshot>()
let generation = 0
async function load() { const request = ++generation; try { const result = await fetchHealth(); if (request === generation) { data.value = result; error.value = '' } } catch (e) { if (request === generation) { data.value = undefined; error.value = String(e) } } }
watch(() => props.revision, load, { immediate: true })
const diagnosticLabel = (code: string) => ({ health_attention: 'A saúde da memória requer atenção', web_version_mismatch: 'Painel precisa ser reiniciado após atualização', daemon_unavailable: 'Serviço de memória indisponível', database_unreadable: 'Base inacessível', queue_failed: 'Operação com falha', queue_delayed: 'Processamento atrasado', backup_overdue: 'Backup atrasado', worker_stalled: 'Processamento parado', web_wrong_instance: 'Painel conectado a outra memória', web_access_failure: 'Painel sem acesso à memória', web_unavailable: 'Painel indisponível', claude_capture_delayed: 'Captura do Claude atrasada', codex_capture_delayed: 'Captura do Codex atrasada' }[code] || 'Não foi possível concluir o diagnóstico')
const date = (value: number | null | undefined) => value ? formatDateTime(value * 1000) : 'Ainda não confirmado'
async function act(action: 'backup' | 'verify' | 'restore' | 'retry' | 'probe' | 'diagnose', item?: BackupSnapshot) {
  busy.value = true; error.value = ''; notice.value = ''
  try {
    if (action === 'probe') { const result = await runMemoryProbe(); if (result.status !== 'passed') throw new Error('A prova de memória encontrou uma falha. Confira os resultados abaixo.'); notice.value = 'Captura, persistência, retomada entre processos e restauração verificadas com dados de teste.' }
    else if (action === 'diagnose') { await runDiagnostics(); notice.value = 'Diagnóstico atualizado.' }
    else if (action === 'backup') { await createBackup(); notice.value = 'Backup criado e restauração testada.' }
    else if (action === 'verify' && item) { await verifyBackup(item.id); notice.value = 'A cópia foi restaurada em uma área temporária e passou na verificação.' }
    else if (action === 'restore' && item) { const result = await restoreBackup(item.id); notice.value = `Dados recuperados em ${result.destination}. A base em uso foi preservada.`; confirm.value = false }
    else if (action === 'retry') { const result = await retryPending(); notice.value = `${result.scheduled} operações agendadas para nova tentativa.` }
    await load()
  } catch (e) { await load(); error.value = String(e); confirm.value = false } finally { busy.value = false }
}
</script>
<template><div class="stack">
  <MAlert v-if="error" title="Não foi possível concluir" :description="error" tone="error" announce><template #actions><MButton @click="load">Atualizar estado</MButton></template></MAlert>
  <MAlert v-if="notice" title="Recuperação" :description="notice" tone="success" announce />
  <p v-if="!data && !error" role="status">Conferindo memória e backups…</p>
  <template v-if="data">
    <MCard gap="md"><div class="row between wrap"><h2>Estado da memória</h2><MBadge :text="data.status === 'healthy' ? 'Disponível' : 'Precisa de atenção'" :tone="data.status === 'healthy' ? 'success' : 'warning'" /></div><ul v-if="data.issues.length" class="evidence-list"><li v-for="issue in data.issues" :key="issue">{{ issue }}</li></ul><p v-else>O serviço está respondendo e as bases podem ser abertas. Confira abaixo as datas de backup e restauração.</p><div class="row wrap"><MBadge :text="data.daemon.running ? 'Serviço conectado' : 'Serviço indisponível'" :tone="data.daemon.running ? 'success' : 'danger'" /><MBadge :text="data.services.daemon?.installed && data.services.web?.installed ? 'Inicia ao entrar no macOS' : 'Inicialização ao entrar não configurada'" tone="neutral" /><small>Versão {{ data.version }} · {{ formatSize(data.disk_free_bytes) }} livres</small></div></MCard>
    <div class="cluster-grid"><MCard gap="md"><small>ÚLTIMA GRAVAÇÃO CONFIRMADA</small><h3>{{ date(data.last_saved_at) }}</h3><p class="muted">Conhecimento ou ponto de retomada gravado na base.</p></MCard><MCard gap="md"><small>ÚLTIMO BACKUP VERIFICADO</small><h3>{{ date(data.backups[0]?.verified_at) }}</h3><p class="muted">{{ data.policy.auto_backup ? `A cada ${data.policy.interval_hours} horas; até ${data.policy.keep} cópias.` : 'Backup automático desativado.' }}</p></MCard><MCard gap="md"><small>ÚLTIMO TESTE DE RESTAURAÇÃO</small><h3>{{ date(data.last_restore_test_at) }}</h3><p class="muted">Uma cópia recuperada foi aberta e conferida.</p></MCard></div>
    <div class="two-columns"><MCard gap="md"><div class="row between wrap"><h2>Operações pendentes</h2><MBadge :text="String(data.queue.pending)" :tone="data.queue.failures ? 'warning' : 'neutral'" /></div><p>{{ data.queue.pending ? 'Estas operações estão em disco e aguardam processamento. Falhas recebem novas tentativas automaticamente.' : 'Nenhuma operação aguardando processamento.' }}</p><p v-if="data.queue.failures">{{ data.queue.failures }} com falha · mais antiga {{ date(data.queue.oldest_at) }}</p><MButton v-if="data.queue.pending" variant="secondary" :loading="busy" @click="act('retry')">Tentar pendências novamente</MButton><small>Último processamento: {{ date(data.last_processed_at) }}</small></MCard><MCard gap="md"><h2>Retomada do trabalho</h2><MBadge :text="data.policy.auto_checkpoints ? 'Captura automática configurada' : 'Captura automática desativada'" :tone="data.policy.auto_checkpoints ? 'neutral' : 'warning'" /><p>O pedido, arquivos alterados e último relato do assistente formam um ponto de retomada parcial. Conclusões e testes precisam ser conferidos ao continuar. O recebimento de eventos é confirmado por cliente abaixo.</p><MButton variant="secondary" href="#tasks">Ver pontos de retomada</MButton></MCard></div>
    <h2>Clientes conectados</h2><div class="two-columns"><MCard v-for="(client, name) in data.clients" :key="name" gap="md"><h3>{{ name === 'codex' ? 'Codex' : 'Claude Code' }}</h3><MBadge :text="client.last_hook_at ? 'Eventos recebidos' : client.configured ? 'Configurado; aguardando sessão' : 'Não configurado'" :tone="client.last_hook_at ? 'success' : 'warning'" /><p>Captura: {{ date(client.last_received_at || client.last_hook_at) }}</p><p>Gravação: {{ date(client.last_saved_at) }}</p><p>Contexto entregue: {{ date(client.last_context_at) }}</p><small>Última conexão das ferramentas: {{ date(client.last_mcp_at) }}</small><p v-if="name === 'codex' && client.configured && !client.last_hook_at" class="muted">Abra uma nova sessão do Codex e revise os hooks do Cortex em /hooks. A autorização é feita no próprio Codex.</p></MCard></div>
    <MCard gap="md"><div class="row between wrap"><h2>Prova de memória entre sessões</h2><MBadge :text="data.self_test?.status === 'passed' ? 'Teste local aprovado' : data.self_test?.status === 'failed' ? 'Teste com falha' : 'Ainda não testado'" :tone="data.self_test?.status === 'passed' ? 'success' : 'warning'" /></div><p>Verifica captura, gravação, recuperação em outro processo, compartilhamento por MCP e restauração de backup. Usa dados descartáveis; a ativação dos seus clientes é conferida acima.</p><small>Última prova: {{ date(data.self_test?.completed_at) }} · {{ data.self_test?.checks?.filter(check => check.passed).length || 0 }} etapas aprovadas</small><MButton variant="secondary" :loading="busy" @click="act('probe')">Testar memória entre sessões</MButton></MCard>
    <MCard gap="md"><div class="row between wrap"><h2>Diagnóstico contínuo</h2><MButton variant="secondary" :loading="busy" @click="act('diagnose')">Diagnosticar agora</MButton></div><p>O serviço confere o funcionamento a cada minuto e mantém as últimas 100 mudanças de estado, sem guardar conversas.</p><small>Última conferência: {{ date(data.diagnostics?.checked_at) }}</small><ul class="evidence-list"><li v-for="event in [...(data.diagnostics?.events || [])].reverse().slice(0, 8)" :key="event.at">{{ date(event.at) }} · {{ event.codes.length ? event.codes.map(diagnosticLabel).join('; ') : 'Serviços respondendo; verificações sem falha' }}</li></ul><p v-if="!data.diagnostics?.events?.length" class="muted">Aguardando a primeira conferência.</p></MCard>
    <div class="row between wrap"><h2>Backups locais</h2><MButton icon="shield-check" :loading="busy" @click="act('backup')">Criar backup agora</MButton></div><p class="muted">{{ data.policy.mirror_configured ? 'Uma segunda pasta de backup está configurada.' : 'Estas cópias ficam neste computador. Uma segunda cópia em outro dispositivo ainda não está configurada.' }}</p>
    <MEmptyState v-if="!data.backups.length" title="Primeiro backup pendente" description="Crie uma cópia agora ou aguarde o serviço executar o backup automático." icon="archive" />
    <MCard v-for="item in data.backups.slice(0, 8)" :key="item.id" gap="md"><div class="row between wrap"><div><h3>{{ date(item.created_at) }}</h3><small>{{ item.files }} arquivos · {{ formatSize(item.size) }}</small></div><MBadge text="Integridade verificada" tone="success" /></div><small class="path">{{ item.id }}</small><div class="row wrap"><MButton variant="secondary" :disabled="busy" @click="act('verify', item)">Testar restauração</MButton><MButton variant="ghost" :disabled="busy" @click="selected = item; confirm = true">Recuperar uma cópia</MButton></div></MCard>
  </template>
  <MDialog v-model:open="confirm" title="Recuperar este backup?" description="Os dados serão restaurados em uma pasta separada. A base em uso será preservada; esta ação não troca a memória atual." confirm-label="Recuperar cópia" cancel-label="Cancelar" :loading="busy" @confirm="act('restore', selected)" />
</div></template>
